<script setup lang="ts">import { ref, onMounted, onUnmounted, computed } from "vue"
import { scv, cx } from "css-variants"
import RLVButton from "@rimelight/ui/components/vue/RLVButton.vue"
import { useRC, useQuickActions } from "@/composables"/* region Props */export interface QuickActionsProps {  rc?: {    root?: string    triggerButton?: string    triggerIcon?: string  }}const { rc: rcProp } = defineProps<QuickActionsProps>()const { rc } = useRC("QuickActions", rcProp)/* endregion *//* region Emits */export interface QuickActionsEmits {}defineEmits<QuickActionsEmits>()/* endregion *//* region Slots */export interface QuickActionsSlots {}defineSlots<QuickActionsSlots>()/* endregion *//* region Styles */const quickActionsStyles = scv({  slots: ["root", "triggerButton", "triggerIcon"],  base: {    root: "relative inline-block",    triggerButton:      "rounded-full size-14 lg:size-12 justify-center shadow-lg hover:scale-110 transition-transform",    triggerIcon: "size-6"  }})const styles = computed(() => {  const resolved = quickActionsStyles()  const result: Record<string, string> = {}  for (const [slot, value] of Object.entries(resolved)) {    result[slot] = cx(value, (rc.value as Record<string, string>)[slot])  }  return result})/* endregion *//* region State */const { registeredActions } = useQuickActions()const menuItems = computed(() => {  const grouped = registeredActions.value.reduce(    (acc, action) => {      const groupId = action.group ?? 0      if (!acc[groupId]) acc[groupId] = []      acc[groupId].push({        label: action.label,        icon: action.icon,        onSelect: action.onSelect      })      return acc    },    {} as Record<number, { label: string; icon?: string; onSelect?: () => void }[]>  )  return Object.values(grouped)})const isOpen = ref(false)const dropdownRef = ref<HTMLElement | null>(null)const handleClickOutside = (event: MouseEvent) => {  if (dropdownRef.value && !dropdownRef.value.contains(event.target as Node)) {    isOpen.value = false  }}onMounted(() => {  document.addEventListener("click", handleClickOutside)})onUnmounted(() => {  document.removeEventListener("click", handleClickOutside)})/* endregion *//* region Meta */defineOptions({  name: "QuickActions"})/* endregion */</script><template>  <div v-if="menuItems.length > 0" ref="dropdownRef" :class="styles.root">    <!-- Trigger Button -->    <RLVButton      color="primary"      square      :class="styles.triggerButton"      aria-label="Quick Actions"      @click="isOpen = !isOpen"    >      <span        :class="[          'i-lucide-plus transition-transform duration-200',          isOpen ? 'rotate-45' : '',          styles.triggerIcon        ]"      />    </RLVButton>    <!-- Custom Dropdown Menu -->    <transition      enter-active-class="transition duration-100 ease-out"      enter-from-class="transform scale-95 opacity-0 translate-y-2"      enter-to-class="transform scale-100 opacity-100 translate-y-0"      leave-active-class="transition duration-75 ease-in"      leave-from-class="transform scale-100 opacity-100 translate-y-0"      leave-to-class="transform scale-95 opacity-0 translate-y-2"    >      <div        v-if="isOpen"        class="absolute right-0 bottom-16 z-50 mb-2 w-48 rounded-xl border border-neutral-200 dark:border-neutral-800 bg-white dark:bg-neutral-900 p-2 shadow-2xl flex flex-col gap-1"      >        <div v-for="(group, gIdx) in menuItems" :key="gIdx" class="flex flex-col gap-1">          <div v-if="gIdx > 0" class="border-t border-neutral-100 dark:border-neutral-800 my-1" />          <button            v-for="item in group"            :key="item.label"            class="w-full flex items-center gap-2 px-3 py-2 rounded-lg text-sm text-left hover:bg-neutral-100 dark:hover:bg-neutral-800 text-neutral-700 dark:text-neutral-300 transition-colors"            @click="              () => {                item.onSelect?.()                isOpen = false              }            "          >            <span              v-if="item.icon"              :class="['size-4 shrink-0', item.icon.replace('lucide:', 'i-lucide-')]"            />            <span>{{ item.label }}</span>          </button>        </div>      </div>    </transition>  </div></template>